// ListProvidersIter returns an iterator that iterates
// over the results of ListProviders.
//
// For example:
//
//	for item, err := range c.ListProvidersIter(ctx, &ListProvidersRequest{}) {
//	  if err != nil {
//	    return err
//	  }
//	  fmt.Println(item)
//	}
//
// Options opts are passed to each ListProviders call
// made by the iterator under the hood.
//
// Callers who need custom pagination logic should use
// ListProviders directly.
func (c *internalClient) ListProvidersIter(ctx context.Context, req *ListProvidersRequest, opts ...call.Option) iter.Seq2[*ProviderInfo, error] {
	return func(yield func(*ProviderInfo, error) bool) {
		// Deep copy the request via JSON round-trip to avoid modifying the original.
		reqBody, err := json.Marshal(req)
		if err != nil {
			yield(nil, err)
			return
		}
		pageReq := ListProvidersRequest{}
		if err := json.Unmarshal(reqBody, &pageReq); err != nil {
			yield(nil, err)
			return
		}
		for {
			resp, err := c.ListProviders(ctx, &pageReq, opts...)
			if err != nil {
				yield(nil, err)
				return
			}
			for i := range resp.Providers {
				if !yield(&resp.Providers[i], nil) {
					return
				}
			}
			if resp.NextPageToken == nil || *resp.NextPageToken == "" {
				return
			}
			pageReq.PageToken = resp.NextPageToken
		}
	}
}

